    { q: 'Kb. mekkora az egyszerű reakcióidő fényjelre?', options: ['2 s', '0,02 s', '1 s', '0,2–0,25 s'], answer: 3, explain: 'Fényre kb. 0,2–0,25 s, hangra kb. 0,15–0,17 s.' },
    { q: 'Mi történik a reakcióidővel, ha több lehetőség közül kell választani?', options: ['Nullára csökken', 'Nem változik', 'Hosszabb lesz', 'Rövidebb lesz'], answer: 2, explain: 'Minél több a választási lehetőség, annál hosszabb.' },
    { q: 'Kb. mennyi idő alatt ér át egy 200 km/h-s teniszszerva a pályán?', options: ['0,05 s', '2 s', 'Kb. 0,5 s', '5 s'], answer: 2, explain: '200 km/h ≈ 56 m/s; kb. 24 m-en lassulással együtt kb. 0,5 s.' },
    { q: 'Mit jelent az anticipáció a sportban?', options: ['Egy szabálytalanság', 'Késlekedés', 'Pihenőidő', 'Az ellenfél mozdulataiból az esemény előre „olvasása”'], answer: 3, explain: 'A szakértők a fontos jeleket hamarabb észreveszik.' },
    { q: 'Melyik agyterület felel főleg a mozgások finomhangolásáért?', options: ['Agyalapi mirigy', 'Szaglógumó', 'Nyakszirti lebeny', 'Kisagy'], answer: 3, explain: 'A kisagy a koordinációért és a begyakorolt mozdulatokért felel.' },
    { q: 'Ki írta le a fejlődési szemléletet (growth mindset)?', options: ['Isaac Newton', 'Pierre de Coubertin', 'Sigmund Freud', 'Carol Dweck'], answer: 3, explain: 'Carol Dweck pszichológus.' },
    { q: 'Mit mutatnak az újabb nagy vizsgálatok a rövid mindset-tréningekről?', options: ['Csodaszerek', 'Ártalmasak', 'Teljesen hatástalanok mindenkinél', 'Átlagos hatásuk szerény, de bizonyos csoportoknál kimutatható'], answer: 3, explain: 'Nem csodaszer, de a hibáról való gondolkodás módja számít.' },
    { q: 'Melyik a fejlődési szemléletre jellemző gondolat?', options: ['„Csak a győzelem számít.”', '„A hiba szégyen.”', '„Ehhez nincs tehetségem, felesleges próbálni.”', '„Még nem megy, de gyakorlással és jó módszerrel fejlődhetek.”'], answer: 3, explain: 'A „még nem” a fejlődés lehetőségét hangsúlyozza.' },
    { q: 'Mi a jó első kérdés egy vereség után (miután kicsit feldolgoztad)?', options: ['Miért mindig én vesztek?', 'Abbahagyjam?', 'Mit tanultam belőle, mi múlt rajtam?', 'Ki a hibás?'], answer: 2, explain: 'A hiba információ, nem ítélet.' },
    { q: 'Mit jelent a fair play?', options: ['Döntetlenre játszani', 'Az ellenfél és a bíró tisztelete, a szabályok szellemének betartása', 'Bármi áron győzni', 'Csak barátokkal játszani'], answer: 1, explain: 'A sport értékének alapja.' },
    { q: 'Mit tegyél, ha a sport már csak teher, szorongsz, nem alszol?', options: ['Beszélj egy felnőttel: szülő, edző, iskolapszichológus', 'Eddz még többet', 'Titkold el', 'Hagyd abba az evést'], answer: 0, explain: 'A lelki egészség ugyanolyan fontos, mint a testi.' }
